reader = csv.reader(csv_data.strip().splitlines())
headers = next(reader)

products = []
index = 1

for row in reader:
    if not row or not any(row):
        continue
    name = row[0].strip()
    if not name or name.startswith('গুরুত্বপূর্ণ'):
        continue
    variety = row[1].strip() if len(row) > 1 else '—'
    img = row[2].strip() if len(row) > 2 else ''
    sowing_time = row[3].strip() if len(row) > 3 else ''
    guide = row[4].strip() if len(row) > 4 else ''
    harvest_time = row[5].strip() if len(row) > 5 else ''

    category = 'veg'
    name_lower = name.lower()
    if 'ফুল' in name_lower or 'জিনিয়া' in name_lower or 'কসমস' in name_lower or 'পদ্ম' in name_lower:
        category = 'ful'
    elif 'ফল' in name_lower or 'মেলন' in name_lower or 'তরমুজ' in name_lower or 'প্যাশন' in name_lower or 'সাম্মাম' in name_lower:
        category = 'fruit'
    elif 'পেনিওয়ার্ট' in name_lower or 'কয়েন' in name_lower or 'বাগান' in name_lower:
        category = 'other'

    prod = {
        'id': f'prod_{index}',
        'name': name,
        'category': category,
        'price': 99,
        'originalPrice': 200,
        'discount': 51,
        'cashback': 0,
        'stock': 100,
        'rating': 5,
        'reviewsCount': 12,
        'image': img,
        'images': [img] if img else [],
        'imageEmoji': '🌱',
        'badgeTags': ['হট ডিল', '৫০% ছাড়', 'প্রিমিয়াম বীজ'],
        'description': f"{name} — উচ্চ ফলনশীল ও ল্যাব পরীক্ষিত প্রিমিয়াম বীজ।\\nজাত: {variety if variety != '—' else 'উন্নত জাত'}\\nবপনের সময়: {sowing_time}\\nফলন/ফুল পেতে সময়: {harvest_time}",
        'germinationDays': harvest_time or '৩-৭ দিন',
        'season': sowing_time or 'বারোমাসি',
        'packSize': '১ প্যাকেট (বীজ)',
        'plantingTip': guide or 'উপযুক্ত টব বা বেডে জৈব সার মিশ্রিত ঝুরঝুরে মাটিতে বীজ বপন করুন। হালকা পানি স্প্রে করে আর্দ্রতা ধরে রাখুন।',
        'popular': index <= 10,
        'seedType': variety if variety != '—' else 'হাইব্রিড / প্রিমিয়াম',
        'germinationRate': '৯৫%+',
        'active': True
    }
    products.append(prod)
    index += 1

ts_content = "import { Product } from '../types';\n\nexport const INITIAL_PRODUCTS_DATA: Product[] = " + json.dumps(products, ensure_ascii=False, indent=2) + ";\n"

os.makedirs('src/data', exist_ok=True)
with open('src/data/initialProducts.ts', 'w', encoding='utf-8') as f:
    f.write(ts_content)

print(f'Successfully parsed and saved {len(products)} products to src/data/initialProducts.ts')
